window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[200]={"id":"200","numero":200,"titre":"Douleur, épanchement articulaire, arthrite récente","objectifs":[{"id":"200-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un épanchement articulaire","contenu":"<div class=\"obj-callout success\"><strong><span class=\"kw-def\">Épanchement articulaire</span></strong> — accumulation <span class=\"kw-clinique\">pathologique</span> de <span class=\"kw-bio\">liquide synovial</span> dans la <span class=\"kw-def\">cavité articulaire</span>. Il traduit <strong>toujours</strong> une <span class=\"kw-alerte\">souffrance intra-articulaire</span>, d'origines diverses (<span class=\"kw-etio\">mécanique</span>, <span class=\"kw-etio\">inflammatoire</span>, <span class=\"kw-etio\">septique</span> ou <span class=\"kw-etio\">hémorragique</span>).</div>\n\n      <p><strong>Rappel physiologique</strong> :</p>\n      <ul>\n        <li>Il existe normalement un <span class=\"kw-bio\">faible film de liquide synovial</span> qui <strong>n'est pas visible</strong> dans la plupart des cas — même avec des examens sensibles (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">IRM</span>).</li>\n        <li>Toute quantité <span class=\"kw-clinique\">détectable</span> de liquide est donc, par définition, <span class=\"kw-clinique\">pathologique</span> : sa simple constatation impose d'en chercher la <span class=\"kw-etio\">cause</span>.</li>\n        <li>Le <span class=\"kw-bio\">liquide synovial</span> est sécrété par la <span class=\"kw-def\">membrane synoviale</span> et lubrifie l'<span class=\"kw-def\">articulation</span> (riche en <span class=\"kw-bio\">acide hyaluronique</span>).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 129 — Arthrose · 196 — Polyarthrite rhumatoïde · 198 — Arthropathie microcristalline</em></p>","frequence":0},{"id":"200-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une arthrite aiguë","contenu":"<div class=\"obj-callout success\"><strong><span class=\"kw-def\">Arthrite</span></strong> — atteinte <span class=\"kw-clinique\">inflammatoire</span> d'une ou plusieurs articulations. Une arthrite est dite <span class=\"kw-def\">aiguë</span> lorsqu'elle évolue depuis <span class=\"kw-chiffre\">&lt; 3 mois</span> ; au-delà de <span class=\"kw-chiffre\">&gt; 3 mois</span>, elle est <span class=\"kw-def\">chronique</span>.</div>\n\n      <p>On caractérise une arthrite selon <strong>quatre axes</strong> :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Caractérisation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Nombre d'articulations</strong></td>\n            <td>\n              <span class=\"kw-def\">Monoarthrite</span> : <span class=\"kw-chiffre\">1</span> articulation<br>\n              <span class=\"kw-def\">Oligoarthrite</span> : <span class=\"kw-chiffre\">2 ou 3</span> articulations<br>\n              <span class=\"kw-def\">Polyarthrite</span> : <span class=\"kw-chiffre\">≥ 4</span> articulations\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mode d'évolution</strong></td>\n            <td>\n              <span class=\"kw-def\">Aiguë</span> (<span class=\"kw-chiffre\">&lt; 3 mois</span>) : fait suspecter une cause <span class=\"kw-etio\">infectieuse</span> ou <span class=\"kw-etio\">microcristalline</span><br>\n              <span class=\"kw-def\">Chronique</span> (<span class=\"kw-chiffre\">&gt; 3 mois</span>) : oriente vers un <span class=\"kw-etio\">rhumatisme inflammatoire</span>, plus rarement une infection à germe lent (<span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">maladie de Lyme</span>)<br>\n              <span class=\"kw-clinique\">Caractère récurrent</span> : évoque une <span class=\"kw-etio\">arthrite microcristalline</span> ou un <span class=\"kw-etio\">rhumatisme inflammatoire</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>\n              Atteinte <span class=\"kw-clinique\">distale et symétrique</span> → <span class=\"kw-etio\">polyarthrite rhumatoïde</span><br>\n              Monoarthrite de la <span class=\"kw-clinique\">métatarso-phalangienne</span> → <span class=\"kw-etio\">goutte</span><br>\n              Oligoarthrite <span class=\"kw-clinique\">asymétrique des membres inférieurs</span> → <span class=\"kw-etio\">spondyloarthrite périphérique</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fièvre associée</strong></td>\n            <td>\n              Étiologie <span class=\"kw-alerte\">septique +++</span><br>\n              Étiologie <span class=\"kw-etio\">microcristalline</span> (plus rarement)<br>\n              Étiologie <span class=\"kw-etio\">rhumatismale</span> (maladie de Still, polyarthrite rhumatoïde)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 196 — Polyarthrite rhumatoïde · 197 — Spondylarthrite inflammatoire · 198 — Arthropathie microcristalline</em></p>","frequence":2},{"id":"200-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","contenu":"<div class=\"callout callout-info\"><strong>Enjeu.</strong> Le rythme de la douleur est l'élément <strong>clé</strong> d'orientation : il sépare une <span class=\"kw-def\">douleur mécanique</span> (lésionnelle, arthrosique) d'une <span class=\"kw-def\">douleur inflammatoire</span> (synoviale, rhumatisme/infection). C'est l'<strong>interrogatoire</strong> qui fait la différence.</div>\n\n      <table >\n        <thead><tr><th>Critère</th><th>Douleur mécanique</th><th>Douleur inflammatoire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Effort</strong></td>\n            <td><span class=\"kw-clinique\">Aggravée par l'effort</span>, ou au <span class=\"kw-clinique\">décours de l'effort</span></td>\n            <td><span class=\"kw-clinique\">Améliorée par l'effort</span></td>\n          </tr>\n          <tr>\n            <td><strong>Repos</strong></td>\n            <td><span class=\"kw-clinique\">Calmée par le repos</span></td>\n            <td><span class=\"kw-clinique\">Non calmée par le repos</span></td>\n          </tr>\n          <tr>\n            <td><strong>Horaire</strong></td>\n            <td>Maximale en <span class=\"kw-clinique\">fin de journée</span> ; sans réveil nocturne, sauf au <span class=\"kw-clinique\">changement de position</span></td>\n            <td><span class=\"kw-clinique\">Aggravée en 2ᵉ partie de nuit</span>, avec <span class=\"kw-clinique\">réveils nocturnes</span></td>\n          </tr>\n          <tr>\n            <td><strong>Dérouillage matinal</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 30 min</span></td>\n            <td><span class=\"kw-chiffre\">&gt; 45 min</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>🚩 Piège classique.</strong> La <span class=\"kw-alerte\">sensibilité aux AINS et aux corticoïdes ne permet PAS</span> de différencier une <span class=\"kw-def\">douleur mécanique</span> d'une <span class=\"kw-def\">douleur inflammatoire</span> : les deux peuvent répondre à ces traitements.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 129 — Arthrose · 196 — Polyarthrite rhumatoïde</em></p>","frequence":4},{"id":"200-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un épanchement articulaire","contenu":"<div class=\"obj-callout success\"><strong>Le diagnostic d'un <span class=\"kw-def\">épanchement articulaire</span> est avant tout <span class=\"kw-clinique\">clinique</span></strong> — l'imagerie ne sert qu'en cas de doute ou d'articulation profonde.</div>\n\n      <p><strong>Examen clinique</strong> :</p>\n      <ul>\n        <li><strong>Inspection</strong> : <span class=\"kw-clinique\">tuméfaction globale</span> de l'articulation, avec <span class=\"kw-clinique\">diminution des reliefs anatomiques</span>.</li>\n        <li><strong>Palpation</strong> : confirme cliniquement l'épanchement (ex. <span class=\"kw-clinique\">choc patellaire</span> au niveau du genou ; <span class=\"kw-clinique\">flot rotulien</span>).</li>\n        <li><strong>Articulations profondes</strong> (<span class=\"kw-clinique\">hanche</span>, <span class=\"kw-clinique\">épaule</span> à moindre degré) : recherche directe <span class=\"kw-alerte\">impossible</span> — seule la <span class=\"kw-clinique\">limitation douloureuse</span> des amplitudes est analysable.</li>\n      </ul>\n\n      <p><strong>Imagerie</strong> (en complément, si besoin) :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Échographie</span> : confirme l'épanchement en cas de <span class=\"kw-clinique\">doute</span> ou d'<span class=\"kw-clinique\">articulation profonde</span> (ex. hanche) ; elle permet aussi de <strong>guider la ponction</strong> (articulation difficile à ponctionner ou faible volume).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>CAT.</strong> La <span class=\"kw-ttt\">ponction articulaire</span> est <strong>systématique</strong> devant la constatation clinique d'un <span class=\"kw-clinique\">épanchement inexpliqué</span> : c'est elle qui permettra le <span class=\"kw-bio\">diagnostic étiologique</span> (<span class=\"kw-bio\">cytologie</span>, <span class=\"kw-bio\">microbiologie</span>, recherche de <span class=\"kw-bio\">cristaux</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 198 — Arthropathie microcristalline</em></p>","frequence":2},{"id":"200-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître trois diagnostics différentiels d’un épanchement articulaire","contenu":"<p>Avant de retenir un véritable <span class=\"kw-def\">épanchement intra-articulaire</span>, il faut écarter les <span class=\"kw-clinique\">tuméfactions péri-articulaires</span> qui le miment. Point commun discriminant : les <span class=\"kw-clinique\">amplitudes articulaires sont conservées</span> dans les diagnostics différentiels.</p>\n      <table >\n        <thead><tr><th>Diagnostic différentiel</th><th>Caractéristique distinctive</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Ténosynovite</strong></span></td>\n            <td>Épanchement situé dans les <span class=\"kw-clinique\">gaines synoviales tendineuses</span> (tendons passant sur une zone de friction : <span class=\"kw-clinique\">cheville</span>, extenseurs des doigts). La <span class=\"kw-clinique\">tuméfaction</span> est <strong>autour du tendon</strong>, pas dans la <span class=\"kw-def\">cavité articulaire</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Bursite / Hygroma</strong></span></td>\n            <td>Inflammation d'une <span class=\"kw-clinique\">bourse séreuse de glissement</span> : les <strong>amplitudes articulaires ne sont pas limitées</strong>, la <span class=\"kw-clinique\">mobilisation passive est conservée</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Érysipèle</strong></span></td>\n            <td><span class=\"kw-clinique\">Érythème superficiel</span> mobile, <strong>sans limitation articulaire</strong> (<span class=\"kw-etio\">dermohypodermite</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Thrombose veineuse profonde (TVP)</strong></span></td>\n            <td><span class=\"kw-clinique\">Œdème douloureux des parties molles</span>, sans atteinte de la cavité articulaire.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"200-6","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les modalités du diagnostic d’une arthrite septique","contenu":"<div class=\"callout callout-danger\"><strong>🚩 Dogme.</strong> <span class=\"kw-alerte\">Toute monoarthrite est une arthrite septique jusqu'à preuve du contraire</span> — c'est une <strong>urgence diagnostique et thérapeutique</strong>.</div>\n\n      <p><strong>Geste diagnostique central — la <span class=\"kw-ttt\">ponction articulaire</span></strong> :</p>\n      <ul>\n        <li>À réaliser <strong>en urgence</strong> et <span class=\"kw-alerte\">avant toute antibiothérapie ou corticothérapie</span> (sinon faux-négatifs des cultures).</li>\n        <li>Aspect macroscopique évocateur : liquide <span class=\"kw-bio\">puriforme</span> (aspect laiteux), <span class=\"kw-bio\">trouble</span>, parfois <span class=\"kw-bio\">purulent + hémorragique</span> dans les formes sévères.</li>\n        <li><span class=\"kw-bio\">Analyse cytologique</span> : liquide <span class=\"kw-bio\">inflammatoire</span> (<span class=\"kw-chiffre\">&gt; 2 000 leucocytes/mL</span>) à prédominance de <span class=\"kw-bio\">PNN</span> — mais la <strong>formule n'est pas spécifique</strong> de l'étiologie.</li>\n        <li><span class=\"kw-bio\">Analyse microbiologique</span> indispensable : <span class=\"kw-bio\">examen direct</span> + <span class=\"kw-bio\">culture</span>, à <strong>prolonger <span class=\"kw-chiffre\">14 jours</span></strong> si forte suspicion ; mise en <span class=\"kw-bio\">mycobactériologie</span> réservée à la suspicion de <span class=\"kw-etio\">tuberculose articulaire</span>.</li>\n      </ul>\n\n      <p><strong>Bilan complémentaire orienté</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Hémocultures</span> à la recherche de la <span class=\"kw-etio\">porte d'entrée</span> / bactériémie ; recherche de porte d'entrée (<span class=\"kw-etio\">chirurgie articulaire récente</span>, <span class=\"kw-etio\">infiltration cortisonique</span>…).</li>\n        <li><span class=\"kw-bio\">CRP</span> et <span class=\"kw-bio\">NFS</span> (hyperleucocytose) : <strong>peu d'orientation</strong>, ne confirment pas le diagnostic.</li>\n        <li>La <span class=\"kw-bio\">biopsie synoviale</span> peut parfois être nécessaire pour affirmer le diagnostic.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-imagerie\">Imagerie</span> — signes tardifs (au stade de séquelle, en l'absence de traitement)</strong> :\n        <ul>\n          <li><span class=\"kw-imagerie\">Déminéralisation épiphysaire en bandes</span> (<span class=\"kw-chiffre\">J10-J14</span>)</li>\n          <li><span class=\"kw-imagerie\">Pincement diffus de l'interligne</span> + <span class=\"kw-imagerie\">érosions osseuses sous-chondrales</span> (<span class=\"kw-chiffre\">J21-J28</span>)</li>\n          <li>Signe négatif utile : <strong>pas d'ostéophyte</strong> (à la différence de l'arthrose)</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 198 — Arthropathie microcristalline</em></p>","frequence":3},{"id":"200-7","rang":"B","rubrique":"Étiologies","titre":"Connaître la principale cause d’arthralgie sans arthropathie","contenu":"<div class=\"callout callout-info\"><strong>Arthralgie sans arthropathie</strong> = douleurs articulaires <strong>sans</strong> arthrite ni lésion structurale objectivable. La principale cause à évoquer est la <strong><span class=\"kw-def\">fibromyalgie</span></strong>.</div>\n\n      <p><strong><span class=\"kw-def\">Fibromyalgie</span></strong> — pathologie douloureuse <span class=\"kw-clinique\">chronique diffuse</span> la plus fréquente (douleur <span class=\"kw-def\">nociplastique</span>) :</p>\n      <ul>\n        <li><strong>Terrain</strong> : <span class=\"kw-clinique\">femme</span> (touchée au moins <span class=\"kw-chiffre\">2 ×</span> plus que l'homme) ; prévalence ≈ <span class=\"kw-chiffre\">1,6 %</span>.</li>\n        <li><strong>Douleurs</strong> : d'apparition <span class=\"kw-clinique\">progressive</span>, <span class=\"kw-clinique\">diffuses</span>, prédominant sur les <span class=\"kw-clinique\">zones d'insertion tendino-musculaire</span> ; <span class=\"kw-clinique\">invalidantes</span>, possible <span class=\"kw-clinique\">horaire nocturne</span>.</li>\n        <li><strong>Examen clinique</strong> : <span class=\"kw-clinique\">examen somatique normal</span> (pas de synovite, pas de déformation).</li>\n        <li><strong>Signes associés</strong> : <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">troubles du sommeil</span>, <span class=\"kw-clinique\">paresthésies des extrémités</span>, <span class=\"kw-clinique\">céphalées</span>, troubles digestifs, <span class=\"kw-clinique\">troubles anxiodépressifs</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Critères ACR 2016 / questionnaire <span class=\"kw-def\">FiRST</span></strong> : douleurs diffuses touchant <span class=\"kw-chiffre\">≥ 4/5</span> régions du corps, présentes depuis <span class=\"kw-chiffre\">≥ 3 mois</span>, avec un <span class=\"kw-def\">Index de Douleurs Diffuses (IDD)</span> et une <span class=\"kw-def\">échelle de Sévérité des Symptômes (SS)</span> élevés. <span class=\"kw-bio\">Examens complémentaires limités</span> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">TSH</span>, pas de radiographie en l'absence d'orientation.</div>\n\n      <div class=\"callout callout-info\"><strong>Prise en charge</strong> — <span class=\"kw-clinique\">multimodale</span> : <span class=\"kw-ttt\">activité physique adaptée</span> et <span class=\"kw-ttt\">approches cognitivo-comportementales</span> en <strong>1ʳᵉ intention</strong> ; <span class=\"kw-ttt\">antidépresseurs</span> (tricycliques, <span class=\"kw-ttt\">IRSNa</span>) et <span class=\"kw-ttt\">antiépileptiques</span> (<span class=\"kw-ttt\">gabapentine</span>, <span class=\"kw-ttt\">prégabaline</span>) si besoin. <span class=\"kw-ci\">Opioïdes forts</span>, <span class=\"kw-ci\">corticoïdes</span> et <span class=\"kw-ci\">benzodiazépines</span> : fortement déconseillés.</div>","frequence":0},{"id":"200-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies à évoquer devant une arthrite récente","contenu":"<div class=\"callout callout-danger\"><strong>🚩 Ordre de priorité absolu.</strong> Devant une <span class=\"kw-def\">arthrite récente</span>, on raisonne <strong>par élimination</strong> en commençant par l'urgence : <span class=\"kw-alerte\">septique → microcristalline → rhumatisme inflammatoire</span>.</div>\n\n      <table >\n        <thead><tr><th>Étiologie (ordre d'élimination)</th><th>Éléments d'orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>1. Arthrite septique</strong></span> 🔥<br>(urgence — à éliminer en priorité)</td>\n            <td><span class=\"kw-etio\">Contexte infectieux</span>, <span class=\"kw-etio\">porte d'entrée</span> (chirurgie articulaire, infiltration), <span class=\"kw-clinique\">fièvre</span> ; liquide <span class=\"kw-bio\">puriforme</span>. Une <span class=\"kw-bio\">biopsie synoviale</span> peut être nécessaire.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>2. Rhumatisme microcristallin</strong></span><br>(le plus fréquent)</td>\n            <td><span class=\"kw-etio\">Goutte</span> (cristaux d'<span class=\"kw-bio\">urate de sodium</span>, monoarthrite de la MTP1) ; <span class=\"kw-etio\">chondrocalcinose</span> (cristaux de <span class=\"kw-bio\">pyrophosphate de calcium</span>). Liquide parfois <span class=\"kw-bio\">puriforme</span> en crise aiguë.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>3. Rhumatisme inflammatoire débutant</strong></span><br>(à éliminer en 3ᵉ temps)</td>\n            <td>Atteinte plus souvent <span class=\"kw-clinique\">oligo- ou polyarticulaire</span> ; liquide polymorphe. <span class=\"kw-etio\">Polyarthrite rhumatoïde</span> (distale, symétrique), <span class=\"kw-etio\">spondyloarthrite</span> (oligo asymétrique des MI).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Orientation par la topographie</strong> :\n        <ul>\n          <li>Atteinte <span class=\"kw-clinique\">distale et symétrique</span> → <span class=\"kw-etio\">polyarthrite rhumatoïde</span></li>\n          <li>Monoarthrite de la <span class=\"kw-clinique\">métatarso-phalangienne</span> → <span class=\"kw-etio\">goutte</span></li>\n          <li><span class=\"kw-clinique\">Oligoarthrite asymétrique des membres inférieurs</span> → <span class=\"kw-etio\">spondyloarthrite périphérique</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 196 — Polyarthrite rhumatoïde · 197 — Spondylarthrite inflammatoire · 198 — Arthropathie microcristalline</em></p>","frequence":3},{"id":"200-9","rang":"A","rubrique":"Étiologies","titre":"Connaître les cinq causes principales d’un épanchement articulaire mécanique","contenu":"<div class=\"callout callout-info\"><strong>Contexte.</strong> Un <span class=\"kw-def\">épanchement mécanique</span> donne un liquide <span class=\"kw-bio\">jaune citrin</span>, <span class=\"kw-bio\">translucide</span>, <span class=\"kw-bio\">visqueux</span>, pauvre en cellules (<span class=\"kw-chiffre\">&lt; 2 000 leucocytes/mL</span>), stérile et sans cristaux.</div>\n\n      <p>Les <strong>cinq causes principales</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\"><strong>Arthrose en poussée</strong></span> (cause la plus fréquente)</li>\n        <li><span class=\"kw-etio\"><strong>Lésion méniscale</strong></span></li>\n        <li><span class=\"kw-etio\"><strong>Lésion chondrale / ostéochondrite</strong></span> — visibles à l'<span class=\"kw-imagerie\">IRM</span></li>\n        <li><span class=\"kw-etio\"><strong>Ostéonécrose aseptique</strong></span> — visible précocement à l'<span class=\"kw-imagerie\">IRM</span></li>\n        <li><span class=\"kw-etio\"><strong>Algodystrophie</strong></span> — révélée en général par d'autres symptômes</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Démarche diagnostique</strong> devant un liquide mécanique :\n        <ul>\n          <li>D'abord <span class=\"kw-imagerie\">radiographies</span> + analyse de l'<span class=\"kw-clinique\">âge</span>, du <span class=\"kw-clinique\">mode de début</span> et de la <span class=\"kw-clinique\">localisation</span> de la douleur</li>\n          <li><span class=\"kw-imagerie\">IRM</span> à discuter si les radiographies sont <strong>normales</strong> et sans orientation évidente</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 129 — Arthrose</em></p>","frequence":1},{"id":"200-10","rang":"A","rubrique":"Étiologies","titre":"Connaître les trois causes principales d’un épanchement articulaire inflammatoire","contenu":"<div class=\"callout callout-info\"><strong>Contexte.</strong> Un <span class=\"kw-def\">épanchement inflammatoire</span> donne un liquide <span class=\"kw-bio\">trouble</span>, riche en cellules (<span class=\"kw-chiffre\">&gt; 2 000 leucocytes/mL</span>). La démarche suit un <strong>ordre d'élimination strict</strong>.</div>\n\n      <table >\n        <thead><tr><th>Cause (ordre d'élimination)</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>1. Arthrite septique</strong></span> 🔥</td>\n            <td>Urgence diagnostique, à <strong>éliminer en priorité</strong> : <span class=\"kw-etio\">contexte infectieux</span>, <span class=\"kw-etio\">porte d'entrée</span>, liquide <span class=\"kw-bio\">puriforme</span> ; <span class=\"kw-bio\">biopsie synoviale</span> parfois nécessaire.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>2. Rhumatisme microcristallin</strong></span></td>\n            <td><strong>Le plus fréquent</strong> : <span class=\"kw-etio\">goutte</span>, <span class=\"kw-etio\">chondrocalcinose</span>. Le liquide peut prendre un aspect <span class=\"kw-bio\">puriforme</span> dans les formes aiguës.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>3. Rhumatisme inflammatoire débutant</strong></span></td>\n            <td>À éliminer en <strong>3ᵉ temps</strong> : atteinte plus souvent <span class=\"kw-clinique\">oligo- ou polyarticulaire</span> ; liquide parfois polymorphe (<span class=\"kw-bio\">PNN</span>, <span class=\"kw-bio\">lymphocytes</span>, <span class=\"kw-bio\">monocytes</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 196 — Polyarthrite rhumatoïde · 198 — Arthropathie microcristalline</em></p>","frequence":2},{"id":"200-11","rang":"A","rubrique":"Étiologies","titre":"Connaître les deux causes principales d’une hémarthrose","contenu":"<div class=\"callout callout-info\"><strong><span class=\"kw-def\">Hémarthrose</span></strong> — traduit <strong>toujours</strong> un <span class=\"kw-alerte\">saignement intra-articulaire</span>. Indice clé : le liquide hémorragique est <strong><span class=\"kw-bio\">incoagulable</span></strong> (vs un saignement par <span class=\"kw-clinique\">accident de ponction</span>, qui lui est <span class=\"kw-bio\">coagulable</span>).</div>\n\n      <p>Les <strong>deux causes principales</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\"><strong>Traumatisme</strong></span> avec lésions ligamentaires et/ou ostéoarticulaires — ex. entorse du <span class=\"kw-clinique\">ligament croisé</span> du genou (<strong>la plus fréquente</strong>).</li>\n        <li><span class=\"kw-etio\"><strong>Trouble de la coagulation</strong></span> — surtout l'<span class=\"kw-etio\">hémophilie A</span> (plus rarement B), qui peut être révélée dès la petite enfance par une hémarthrose (à l'acquisition de la marche).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Autres causes (plus rares)</strong> :\n        <ul>\n          <li><span class=\"kw-etio\">Microcristaux</span> (chondrocalcinose surtout) ou <span class=\"kw-etio\">infection aiguë</span>, par inflammation aiguë de la synoviale</li>\n          <li><span class=\"kw-etio\">Lésion tumorale</span> de la membrane synoviale (en particulier la <span class=\"kw-def\">synovite villonodulaire</span>)</li>\n          <li>Autres troubles de l'hémostase : <span class=\"kw-etio\">maladie de Willebrand</span>, <span class=\"kw-etio\">thrombopénie</span>, <span class=\"kw-ci\">surdosage en AVK</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 216 — Syndrome hémorragique</em></p>","frequence":0},{"id":"200-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication et non indication des examens d’imagerie devant une douleur, un épanchement articulaire ou une arthrite d’évolution récente","contenu":"<div class=\"callout callout-warn\"><strong>Message-clé.</strong> Devant une atteinte <span class=\"kw-clinique\">récente</span>, l'imagerie a une <strong>valeur d'orientation limitée</strong> : les <span class=\"kw-imagerie\">radiographies</span> sont souvent <span class=\"kw-clinique\">normales initialement</span> et <strong>aident peu</strong> au diagnostic étiologique précoce. Le geste-clé reste la <span class=\"kw-ttt\">ponction articulaire</span>, pas l'imagerie.</div>\n\n      <p><strong><span class=\"kw-imagerie\">Radiographies standards</span> — indiquées</strong>, au minimum <span class=\"kw-imagerie\">bilatérales et comparatives</span> des articulations atteintes :</p>\n      <ul>\n        <li>Peuvent rester <span class=\"kw-clinique\">normales au début</span> ; leur apport est surtout différé.</li>\n        <li>Recherche d'un <span class=\"kw-imagerie\">liseré de chondrocalcinose</span>.</li>\n        <li>Signes <strong>tardifs</strong> d'<span class=\"kw-etio\">arthrite septique</span> (J10-J28) : <span class=\"kw-imagerie\">déminéralisation en bandes</span>, <span class=\"kw-imagerie\">pincement diffus</span>, <span class=\"kw-imagerie\">érosions sous-chondrales</span>, <strong>sans ostéophyte</strong>.</li>\n        <li>Signes <strong>très tardifs</strong> d'<span class=\"kw-etio\">arthropathie uratique</span> : <span class=\"kw-imagerie\">géodes / encoches épiphysaires</span> avec <span class=\"kw-imagerie\">conservation de l'interligne</span> et <span class=\"kw-imagerie\">ostéophytose marginale</span>.</li>\n      </ul>\n\n      <p><strong><span class=\"kw-imagerie\">Échographie</span> — indiquée</strong> en cas de doute clinique :</p>\n      <ul>\n        <li>Confirme l'<span class=\"kw-clinique\">épanchement</span> si articulation <span class=\"kw-clinique\">profonde</span> (hanche) ou faible volume.</li>\n        <li><strong>Guide la ponction</strong> des articulations difficiles d'accès.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Non-indication / à discuter</strong> :\n        <ul>\n          <li>Pas d'<span class=\"kw-imagerie\">imagerie en coupe systématique</span> en urgence devant une arthrite récente non compliquée.</li>\n          <li><span class=\"kw-imagerie\">IRM</span> à <strong>discuter</strong> seulement si les radiographies sont <span class=\"kw-clinique\">normales</span> et qu'il n'y a pas d'orientation évidente (recherche de lésion méniscale, chondrale, ostéonécrose…).</li>\n        </ul>\n      </div>","frequence":1},{"id":"200-13","rang":"A","rubrique":"Examens complémentaires","titre":"Différencier un épanchement mécanique d’un épanchement inflammatoire","contenu":"<div class=\"obj-callout success\"><strong>L'<span class=\"kw-def\">analyse du liquide de ponction</span> tranche</strong> entre épanchement <span class=\"kw-def\">mécanique</span> et <span class=\"kw-def\">inflammatoire</span>. Le seuil de référence est la <span class=\"kw-bio\">cytologie</span> : <span class=\"kw-chiffre\">2 000 leucocytes/mL</span>.</div>\n\n      <table >\n        <thead><tr><th>Paramètre</th><th>Épanchement mécanique</th><th>Épanchement inflammatoire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cytologie (<span class=\"kw-bio\">leucocytes</span>)</strong></td>\n            <td><span class=\"kw-bio\">&lt; 2 000/mL</span></td>\n            <td><span class=\"kw-bio\">&gt; 2 000/mL</span></td>\n          </tr>\n          <tr>\n            <td><strong>Aspect macroscopique</strong></td>\n            <td><span class=\"kw-bio\">Jaune citrin</span>, <span class=\"kw-bio\">translucide</span>, <span class=\"kw-bio\">visqueux</span></td>\n            <td><span class=\"kw-bio\">Trouble</span> et <span class=\"kw-bio\">fluide</span></td>\n          </tr>\n          <tr>\n            <td><strong>Orientation étiologique</strong></td>\n            <td><span class=\"kw-etio\">Arthrose</span>, lésions <span class=\"kw-etio\">méniscales / chondrales</span></td>\n            <td><span class=\"kw-etio\">Septique</span>, <span class=\"kw-etio\">microcristallin</span>, <span class=\"kw-etio\">rhumatisme inflammatoire</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>🚩 Deux aspects à part</strong> :\n        <ul>\n          <li>Liquide <span class=\"kw-bio\">puriforme</span> (laiteux) → <span class=\"kw-alerte\">arthrite septique</span> (à confirmer par la culture)</li>\n          <li>Liquide <span class=\"kw-bio\">hémorragique</span> → <span class=\"kw-alerte\">hémarthrose</span></li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\"><strong>Pièges d'interprétation</strong> :\n        <ul>\n          <li>La <span class=\"kw-bio\">formule</span> du liquide est <strong>peu informative</strong> : une richesse en <span class=\"kw-bio\">PNN</span> n'est <strong>pas spécifique</strong> (infectieux comme rhumatismes inflammatoires).</li>\n          <li>Aucun intérêt de l'<span class=\"kw-ci\">analyse biochimique</span> du liquide articulaire.</li>\n          <li><span class=\"kw-bio\">Analyse microcristalline</span> : <span class=\"kw-bio\">urate de sodium</span> (aiguilles fines, fortement biréfringentes) → <span class=\"kw-etio\">goutte</span> ; <span class=\"kw-bio\">pyrophosphate de calcium</span> (carrés/rectangulaires, peu biréfringents) → <span class=\"kw-etio\">chondrocalcinose</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 198 — Arthropathie microcristalline</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Dogme :</strong> toute <span class=\"kw-etio\">monoarthrite</span> est une <span class=\"kw-alerte\">arthrite septique jusqu'à preuve du contraire</span>.<br><strong>Urgence :</strong> l'<span class=\"kw-etio\">arthrite septique</span> est une <span class=\"kw-alerte\">urgence diagnostique</span> à éliminer en priorité.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">ponction articulaire</span> systématique devant tout épanchement inexpliqué, <span class=\"kw-ttt\">avant tout traitement ATB ou corticoïde</span>.<br><strong>Hémarthrose + infection :</strong> <span class=\"kw-alerte\">urgence médicale</span> nécessitant <span class=\"kw-ttt\">drainage</span> et <span class=\"kw-ttt\">antibiotiques IV</span>.</p>","hospit":"<p><strong>Voie directe :</strong> <span class=\"kw-ttt\">ponction directe</span> possible pour les articulations superficielles (genou, cheville, poignet).<br><strong>Articulation profonde :</strong> la <span class=\"kw-clinique\">hanche</span> nécessite un <span class=\"kw-imagerie\">écho-</span> ou <span class=\"kw-imagerie\">radioguidage</span>.<br><strong>Prothèse articulaire :</strong> ponction <span class=\"kw-ttt\">en milieu chirurgical</span> si possible.<br><strong>Quand :</strong> ponction <span class=\"kw-ttt\">avant tout traitement ATB ou corticoïde</span>.</p>","redflags":"<ul><li><span class=\"kw-etio\">Monoarthrite</span> : <span class=\"kw-alerte\">arthrite septique jusqu'à preuve du contraire</span></li><li><span class=\"kw-alerte\">Fièvre</span> : oriente en priorité (+++) vers une <span class=\"kw-etio\">étiologie septique</span></li><li>Liquide <span class=\"kw-alerte\">puriforme / purulent</span> (aspect laiteux) à la ponction</li><li>Liquide <span class=\"kw-alerte\">purulent + hémorragique</span> : arthrite septique sévère avec hémarthrose</li><li>Contexte infectieux / <span class=\"kw-clinique\">porte d'entrée</span> (chirurgie articulaire récente, infiltration cortisonique)</li><li>Arthrite aiguë (<span class=\"kw-chiffre\">< 3 mois</span>) : fait suspecter une cause <span class=\"kw-etio\">infectieuse</span> ou <span class=\"kw-etio\">microcristalline</span></li></ul>","principes":"<p>La <span class=\"kw-ttt\">ponction articulaire</span> est la clé : systématique devant tout épanchement inexpliqué, réalisée <span class=\"kw-ttt\">avant tout traitement</span>, avec analyse complète du liquide.</p><p><strong>Ponction & analyses du liquide</strong></p><p>Ponction systématique, avant tout ATB ou corticoïde</p><ul><li><strong>Cytologie</strong> : <span class=\"kw-bio\">< 2 000 leucocytes/mL</span> = liquide mécanique ; <span class=\"kw-bio\">> 2 000/mL</span> = liquide inflammatoire</li><li><strong>Microbiologie</strong> : <span class=\"kw-bio\">examen direct + culture</span> (prolongée <span class=\"kw-chiffre\">14 jours</span> si suspicion forte d'infection)</li><li><span class=\"kw-bio\">Mycobactériologie</span> réservée à la suspicion de <span class=\"kw-etio\">tuberculose articulaire</span></li><li><strong>Microcristaux</strong> : <span class=\"kw-bio\">urate de sodium</span> (aiguilles) → <span class=\"kw-etio\">goutte</span> ; <span class=\"kw-bio\">pyrophosphate de calcium</span> (rectangulaires) → <span class=\"kw-etio\">chondrocalcinose</span></li><li>Aucun intérêt d'une <span class=\"kw-bio\">analyse biochimique</span> du liquide</li></ul><p><strong>Contre-indications (relatives) de la ponction</strong></p><p>CI restent relatives en cas de suspicion d'arthrite septique</p><ul><li><span class=\"kw-ci\">Lésion ou infection cutanée</span> au site de ponction</li><li><span class=\"kw-ci\">Matériel prothétique</span> articulaire (à faire en milieu chirurgical)</li><li><span class=\"kw-ci\">Troubles de la coagulation</span> (coagulopathie, anticoagulant suprathérapeutique)</li><li><span class=\"kw-ci\">Thrombopénie < 50 G/L</span> (n'est pas une <span class=\"kw-ci\">contre-indication</span> absolue)</li></ul><p><strong>Biologie d'orientation</strong></p><ul><li><span class=\"kw-bio\">CRP</span> et <span class=\"kw-bio\">NFS</span> : peu de valeur d'orientation</li><li><span class=\"kw-bio\">Hémocultures</span> si cause infectieuse suspectée</li><li><span class=\"kw-bio\">Bilan de coagulation</span> si hémarthrose</li><li><span class=\"kw-bio\">Uricémie > 360 μmol/L</span> oriente vers une <span class=\"kw-etio\">goutte</span> (mais peut être normale lors d'un accès aigu)</li><li><span class=\"kw-bio\">Bilan auto-immun</span> (FR, ACPA, AAN) seulement en fin d'enquête, après élimination des causes septique et cristalline</li></ul><p><strong>Imagerie</strong></p><ul><li><span class=\"kw-imagerie\">Radiographies bilatérales et comparatives</span> (souvent <span class=\"kw-radio\">normales initialement</span>)</li><li><span class=\"kw-imagerie\">Échographie</span> pour confirmer un épanchement profond ou guider la ponction</li><li><span class=\"kw-imagerie\">IRM</span> si radiographies normales et absence d'orientation évidente</li></ul>","suivi":"<p><strong>Culture :</strong> prolongée <span class=\"kw-chiffre\">14 jours</span> si suspicion forte d'<span class=\"kw-etio\">infection</span>.<br><strong>Radiographie :</strong> les <span class=\"kw-radio\">signes d'arthrite septique</span> n'apparaissent qu'après <span class=\"kw-chiffre\">1-2 semaines</span> sans traitement — <span class=\"kw-radio\">déminéralisation épiphysaire en bandes</span> (<span class=\"kw-chiffre\">J10-14</span>), puis <span class=\"kw-radio\">pincement de l'interligne + érosions sous-chondrales</span> (<span class=\"kw-chiffre\">J21-28</span>).<br><strong>Signe négatif :</strong> <span class=\"kw-radio\">pas d'ostéophyte</span> dans l'arthrite septique.</p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-21-0.php","label":"COFER — cours de rhumatologie"},{"href":"https://radiopaedia.org/articles/joint-effusion","label":"Radiopaedia : joint effusion"},{"href":"https://radiopaedia.org/articles/joints-1","label":"Radiopaedia : joints (anatomie articulaire)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Épanchement articulaire récent — Toute monoarthrite = arthrite septique jusqu'à preuve du contraire","detail":"<h4>CAT — Épanchement articulaire / arthrite récente — Démarche centrée sur la ponction articulaire et l'analyse du liquide</h4>","branches":[{"to":"q-ponction","label":"Épanchement confirmé cliniquement (tuméfaction, choc patellaire)","color":"blue"}]},{"id":"q-ponction","kind":"decision","label":"Ponction articulaire — aspect du liquide ? — Systématique devant tout épanchement inexpliqué, avant tout ATB / corticoïde","branches":[{"to":"t-septique","label":"Purulent / puriforme (laiteux)","color":"red"},{"to":"t-hemarthrose","label":"Hémorragique incoagulable","color":"amber"},{"to":"q-inflammatoire","label":"Trouble, fluide (≥ 2 000 leuco/mL)","color":"amber"},{"to":"t-mecanique","label":"Jaune citrin, visqueux (< 2 000 leuco/mL)","color":"green"}]},{"id":"t-septique","kind":"terminal","label":"Arthrite septique — urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Monoarthrite</span> aiguë <span class=\"kw-alerte\">fébrile</span></li><li>Contexte infectieux / <span class=\"kw-clinique\">porte d'entrée</span> (chirurgie articulaire récente, infiltration cortisonique)</li></ul><h4>Paraclinique</h4><ul><li>Liquide <span class=\"kw-alerte\">puriforme / purulent</span> (inflammatoire, <span class=\"kw-bio\">> 2 000 leucocytes/mL</span>)</li><li><span class=\"kw-bio\">Examen direct + culture</span> (prolongée <span class=\"kw-chiffre\">14 j</span>), <span class=\"kw-bio\">hémocultures</span></li><li><span class=\"kw-etio\">Biopsie synoviale</span> parfois nécessaire pour affirmer le diagnostic</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence diagnostique</span> : à éliminer en priorité</li><li><span class=\"kw-ttt\">Ponction avant tout ATB ou corticoïde</span></li><li>Hémarthrose + infection → <span class=\"kw-ttt\">drainage</span> + <span class=\"kw-ttt\">antibiotiques IV</span></li></ul>"},{"id":"t-hemarthrose","kind":"terminal","label":"Hémarthrose — Liquide hémorragique incoagulable","color":"amber","detail":"<h4>Paraclinique</h4><ul><li>Liquide <span class=\"kw-etio\">hémorragique incoagulable</span> (vs accident de ponction = coagulable)</li><li><span class=\"kw-bio\">Bilan de coagulation</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-etio\">Traumatisme</span> ligamentaire : entorse du <span class=\"kw-clinique\">ligament croisé</span> du genou (le plus fréquent)</li><li><span class=\"kw-etio\">Microcristaux</span> (chondrocalcinose) ou <span class=\"kw-etio\">infection aiguë</span> (plus rares)</li><li><span class=\"kw-etio\">Trouble de la coagulation</span> : <span class=\"kw-etio\">hémophilie A</span>, maladie de Willebrand, surdosage en <span class=\"kw-ttt\">AVK</span></li><li><span class=\"kw-etio\">Synovite villonodulaire</span> (rare, tumorale)</li></ul>"},{"id":"q-inflammatoire","kind":"decision","label":"Liquide inflammatoire trouble — orientation — Éliminer d'abord une arthrite septique débutante","branches":[{"to":"t-septique","label":"Examen direct/culture positif ou contexte infectieux","color":"red"},{"to":"t-microcristallin","label":"Microcristaux présents","color":"amber"},{"to":"t-rhumatisme","label":"Aucun cristal, atteinte oligo/polyarticulaire","color":"blue"}]},{"id":"t-microcristallin","kind":"terminal","label":"Rhumatisme microcristallin — Goutte / chondrocalcinose","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Cristaux d'urate de sodium</span> (fins, en aiguille, biréfringents) → <span class=\"kw-etio\">goutte</span></li><li><span class=\"kw-bio\">Cristaux de pyrophosphate de calcium</span> (rectangulaires, courts) → <span class=\"kw-etio\">chondrocalcinose</span></li><li><span class=\"kw-bio\">Uricémie > 360 μmol/L</span> oriente vers la goutte (peut être normale en accès aigu)</li></ul><h4>Clinique</h4><ul><li>Monoarthrite <span class=\"kw-clinique\">métatarso-phalangienne</span> → <span class=\"kw-etio\">goutte</span></li></ul><h4>Conduite</h4><ul><li>Cause la plus fréquente des liquides inflammatoires ; aspect parfois puriforme dans les formes aiguës</li></ul>"},{"id":"t-rhumatisme","kind":"terminal","label":"Rhumatisme inflammatoire débutant — Atteinte plus souvent oligo- ou polyarticulaire","color":"blue","detail":"<h4>Clinique</h4><ul><li>Douleur <span class=\"kw-clinique\">inflammatoire</span> : réveils nocturnes (2e partie de nuit), dérouillage <span class=\"kw-chiffre\">> 45 min</span></li><li>Atteinte distale symétrique → <span class=\"kw-etio\">polyarthrite rhumatoïde</span> ; oligoarthrite asymétrique des MI → <span class=\"kw-etio\">spondyloarthrite</span></li><li>Rechercher des <span class=\"kw-clinique\">signes extra-articulaires</span> (éléments clés du diagnostic)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Bilan auto-immun</span> (FR, ACPA, AAN) en fin d'enquête, après élimination des causes septique et cristalline</li></ul><h4>Conduite</h4><ul><li>À éliminer en 3e temps, après l'arthrite septique puis le rhumatisme microcristallin</li></ul>"},{"id":"t-mecanique","kind":"terminal","label":"Épanchement mécanique — Liquide jaune citrin, visqueux, < 2 000 leuco/mL","color":"green","detail":"<h4>Clinique</h4><ul><li>Douleur <span class=\"kw-clinique\">mécanique</span> : aggravée par l'effort, calmée par le repos, dérouillage <span class=\"kw-chiffre\">< 30 min</span></li></ul><h4>Paraclinique</h4><ul><li>Liquide <span class=\"kw-bio\">jaune citrin, translucide, visqueux</span>, <span class=\"kw-bio\">< 2 000 leucocytes/mL</span>, stérile, sans cristaux</li></ul><h4>Étiologie</h4><ul><li><span class=\"kw-etio\">Arthrose en poussée</span></li><li><span class=\"kw-etio\">Lésions méniscales / chondrales, ostéochondrite</span> (<span class=\"kw-imagerie\">IRM</span>)</li><li><span class=\"kw-etio\">Ostéonécrose aseptique, algodystrophie</span> (<span class=\"kw-imagerie\">IRM</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">RX</span> + âge, mode de début, localisation ; <span class=\"kw-imagerie\">IRM</span> à discuter si RX normales</li></ul>"}]},"cards":[{"i":"61b2c077cdc8","n":200,"o":"200-1","u":"Définition","t":"Connaître la définition d’un épanchement articulaire","q":"Que signifie la présence d'un épanchement articulaire ?","a":"<p>La présence d'un épanchement articulaire traduit toujours une <strong>souffrance intra-articulaire</strong>, dont les origines peuvent être diverses (<strong>mécanique, inflammatoire, septique ou hémorragique</strong>).</p>"},{"i":"758f42161962","n":200,"o":"200-1","u":"Définition","t":"Connaître la définition d’un épanchement articulaire","q":"Quelle est la définition d'un épanchement articulaire ?","a":"<p>Un épanchement articulaire est une <strong>accumulation pathologique de liquide synovial</strong> dans la cavité articulaire.</p>"},{"i":"ca9436c69d98","n":200,"o":"200-1","u":"Définition","t":"Connaître la définition d’un épanchement articulaire","q":"Quand considère-t-on qu'une quantité de liquide synovial est pathologique ?","a":"<p>Toute quantité de liquide synovial <strong>détectable</strong> par les examens (échographie, IRM) est considérée comme <strong>pathologique</strong>, car physiologiquement, seul un faible film non-visible est présent. Sa simple constatation impose donc d'en rechercher la cause.</p>"},{"i":"10f041212f6c","n":200,"o":"200-10","u":"Étiologies","t":"Connaître les trois causes principales d’un épanchement articulaire inflammatoire","q":"Quelle est la première cause à éliminer devant un épanchement articulaire inflammatoire, et pourquoi est-ce une urgence ?","a":"<p>La première cause à éliminer est l'<strong>arthrite septique</strong>. C'est une <strong>urgence diagnostique</strong> en raison du risque de destruction articulaire rapide et de sepsis. Sa recherche est orientée par un contexte infectieux, une porte d'entrée, et un liquide articulaire potentiellement puriforme.</p>"},{"i":"35cf96bcde17","n":200,"o":"200-10","u":"Étiologies","t":"Connaître les trois causes principales d’un épanchement articulaire inflammatoire","q":"Quelles sont les caractéristiques d'un rhumatisme microcristallin aigu, deuxième cause d'épanchement inflammatoire à considérer ?","a":"<p>Le rhumatisme microcristallin (<strong>goutte</strong>, <strong>chondrocalcinose</strong>) est la cause la plus fréquente d'épanchement inflammatoire. Le liquide articulaire, bien que contenant des cristaux, peut prendre un aspect <strong>puriforme</strong> dans les formes aiguës, mimant une infection.</p>"},{"i":"91fb5dc685dd","n":200,"o":"200-10","u":"Étiologies","t":"Connaître les trois causes principales d’un épanchement articulaire inflammatoire","q":"Comment suspecter un rhumatisme inflammatoire débutant face à un épanchement articulaire inflammatoire ?","a":"<p>Un rhumatisme inflammatoire débutant doit être suspecté en troisième intention, notamment si l'atteinte est <strong>oligo- ou polyarticulaire</strong>. Le liquide articulaire peut être <strong>polymorphe</strong> sur le plan cellulaire, avec la présence de polynucléaires neutrophiles (PNN), de lymphocytes et de monocytes.</p>"},{"i":"e079efa3b386","n":200,"o":"200-10","u":"Étiologies","t":"Connaître les trois causes principales d’un épanchement articulaire inflammatoire","q":"Comment doit être caractérisé un épanchement articulaire pour être défini comme inflammatoire ?","a":"<p>Un épanchement articulaire inflammatoire se caractérise par un liquide <strong>trouble</strong> et <strong>riche en cellules</strong>, contenant <strong>plus de 2 000 leucocytes/mL</strong>.</p>"},{"i":"04237297d17e","n":200,"o":"200-11","u":"Étiologies","t":"Connaître les deux causes principales d’une hémarthrose","q":"Quelles sont les autres causes, plus rares, pouvant entraîner une hémarthrose ?","a":"<ul><li>Les <strong>microcristaux</strong> (notamment lors d'une chondrocalcinose) ou une <strong>infection aiguë</strong>, par inflammation synoviale intense.</li><li>Une <strong>lésion tumorale de la membrane synoviale</strong>, en particulier la synovite villonodulaire.</li><li>D'<strong>autres troubles de l'hémostase</strong> comme la maladie de Willebrand, une thrombopénie, ou un surdosage en anti-vitamine K (AVK).</li></ul>"},{"i":"256db16a8f2e","n":200,"o":"200-11","u":"Étiologies","t":"Connaître les deux causes principales d’une hémarthrose","q":"Quelle est la définition et la particularité sémiologique de l'hémarthrose ?","a":"<p>L'hémarthrose correspond à un <strong>saignement intra-articulaire</strong>. Sa particularité est que le liquide hémorragique est <strong>incoagulable</strong>, permettant de le différencier d'un saignement lié à un accident de ponction.</p>"},{"i":"430120a26179","n":200,"o":"200-11","u":"Étiologies","t":"Connaître les deux causes principales d’une hémarthrose","q":"Quelle affection hématologique est une cause majeure d'hémarthrose, notamment chez l'enfant ?","a":"<p>Un <strong>trouble de la coagulation</strong>, notamment l'<strong>hémophilie A</strong> (plus rarement l'hémophilie B), constitue une cause majeure d'hémarthrose et peut être révélée dès la petite enfance, par exemple à l'acquisition de la marche.</p>"},{"i":"fc73dc223410","n":200,"o":"200-11","u":"Étiologies","t":"Connaître les deux causes principales d’une hémarthrose","q":"Quelle est la principale cause d'hémarthrose ?","a":"<p>La principale cause d'hémarthrose est un <strong>traumatisme</strong> entraînant des lésions ligamentaires et/ou ostéoarticulaires, comme une <strong>entorse du ligament croisé antérieur du genou</strong>.</p>"},{"i":"2ac84c4c8d39","n":200,"o":"200-13","u":"Examens complémentaires","t":"Différencier un épanchement mécanique d’un épanchement inflammatoire","q":"Quels sont les pièges d'interprétation et éléments non pertinents lors de l'analyse du liquide articulaire pour différencier un épanchement mécanique d'inflammatoire ?","a":"<p>Les pièges et éléments non pertinents sont :</p><ul><li>La <strong>formule du liquide (richesse en PNN) est peu informative</strong> car non spécifique, présente aussi bien dans les épanchements infectieux que dans les rhumatismes inflammatoires.</li><li>L'<strong>analyse biochimique</strong> du liquide articulaire n'a <strong>aucun intérêt</strong>.</li><li>Un aspect macroscopique puriforme indique une forte suspicion d'<strong>arthrite septique</strong> (nécessite une culture bactériologique).</li><li>Un aspect macroscopique hémorragique oriente vers une <strong>hémarthrose</strong>.</li></ul>"},{"i":"91a51bed4eb9","n":200,"o":"200-13","u":"Examens complémentaires","t":"Différencier un épanchement mécanique d’un épanchement inflammatoire","q":"Quelles sont les caractéristiques macroscopiques et cytologiques d'un épanchement articulaire mécanique ?","a":"<p>Les caractéristiques d'un épanchement articulaire mécanique sont :</p><ul><li><strong>Aspect macroscopique</strong> : Jaune citrin, translucide, visqueux.</li><li><strong>Cytologie</strong> : <strong>< 2 000 leucocytes/mL</strong>.</li><li><strong>Orientation étiologique</strong> : <strong>Arthrose</strong>, lésions méniscales/chondrales.</li></ul>"},{"i":"e1925e1772d8","n":200,"o":"200-13","u":"Examens complémentaires","t":"Différencier un épanchement mécanique d’un épanchement inflammatoire","q":"Quel est le seuil cytologique qui permet de différencier un épanchement articulaire mécanique d'un épanchement inflammatoire ?","a":"<p>La cytologie du liquide de ponction articulaire permet de différencier un épanchement mécanique d'un épanchement inflammatoire. Le seuil de référence est de <strong>2 000 leucocytes/mL</strong>.</p><ul><li>Un épanchement est considéré <strong>mécanique</strong> si la cytologie est <strong>< 2 000 leucocytes/mL</strong>.</li><li>Un épanchement est considéré <strong>inflammatoire</strong> si la cytologie est <strong>> 2 000 leucocytes/mL</strong>.</li></ul>"},{"i":"e82350eaa8c0","n":200,"o":"200-13","u":"Examens complémentaires","t":"Différencier un épanchement mécanique d’un épanchement inflammatoire","q":"Quel est l'intérêt de la recherche de microcristaux dans le liquide articulaire lors de l'analyse d'un épanchement inflammatoire ?","a":"<p>La recherche de microcristaux est indispensable pour diagnostiquer les arthropathies microcristallines :</p><ul><li>Présence d'<strong>urates de sodium</strong> (aiguilles fines, fortement biréfringentes) oriente vers une <strong>goutte</strong>.</li><li>Présence de <strong>pyrophosphate de calcium</strong> (carrés/rectangulaires, peu biréfringents) oriente vers une <strong>chondrocalcinose</strong>.</li></ul>"},{"i":"f0e7b046b277","n":200,"o":"200-13","u":"Examens complémentaires","t":"Différencier un épanchement mécanique d’un épanchement inflammatoire","q":"Quelles sont les caractéristiques macroscopiques et cytologiques d'un épanchement articulaire inflammatoire ?","a":"<p>Les caractéristiques d'un épanchement articulaire inflammatoire sont :</p><ul><li><strong>Aspect macroscopique</strong> : Trouble et fluide.</li><li><strong>Cytologie</strong> : <strong>> 2 000 leucocytes/mL</strong>.</li><li><strong>Orientation étiologique</strong> : Épanchement septique, microcristallin, rhumatisme inflammatoire.</li></ul>"},{"i":"197879db408b","n":200,"o":"200-2","u":"Définition","t":"Connaître la définition d’une arthrite aiguë","q":"Quelle est la définition d'une arthrite en médecine ?","a":"<p>Une arthrite est une <strong>atteinte inflammatoire d'une ou plusieurs articulations</strong>.</p>"},{"i":"4e26b69a1b27","n":200,"o":"200-2","u":"Définition","t":"Connaître la définition d’une arthrite aiguë","q":"Quand une arthrite est-elle définie comme aiguë ?","a":"<p>Une arthrite est dite aiguë lorsqu'elle <strong>évolue depuis moins de 3 mois</strong>.</p>"},{"i":"57cd9ebe14fd","n":200,"o":"200-2","u":"Définition","t":"Connaître la définition d’une arthrite aiguë","q":"Comment différencier une arthrite aiguë d'une arthrite chronique ?","a":"<p>La distinction se fait sur la durée d'évolution : une arthrite est <strong>aiguë si elle évolue depuis moins de 3 mois</strong> et <strong>chronique si elle évolue depuis plus de 3 mois</strong>.</p>"},{"i":"0baec03270e6","n":200,"o":"200-3","u":"Diagnostic positif","t":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","q":"Un patient présentant une douleur améliorée par des AINS a-t-il forcément une douleur inflammatoire ?","a":"<p>Non, ce n'est pas certain. La <strong>sensibilité aux AINS et aux corticoïdes</strong> ne permet <strong>PAS</strong> de différencier une douleur mécanique d'une douleur inflammatoire car les deux peuvent répondre à ces traitements.</p>"},{"i":"532132b0a9d0","n":200,"o":"200-3","u":"Diagnostic positif","t":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","q":"Quelles sont les caractéristiques d'une douleur mécanique, notamment en lien avec l'effort et le repos ?","a":"<ul><li>Elle est <strong>aggravée par l'effort</strong> ou au décours de l'effort.</li><li>Elle est <strong>calmée par le repos</strong>.</li></ul>"},{"i":"7f6f419827cf","n":200,"o":"200-3","u":"Diagnostic positif","t":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","q":"Quelles sont les caractéristiques d'une douleur inflammatoire, notamment en lien avec l'effort et le repos ?","a":"<ul><li>Elle est <strong>améliorée par l'effort</strong>.</li><li>Elle est <strong>non calmée par le repos</strong>.</li></ul>"},{"i":"94619482f763","n":200,"o":"200-3","u":"Diagnostic positif","t":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","q":"Quel est l'élément clé de l'interrogatoire permettant de différencier une douleur mécanique d'une douleur inflammatoire ?","a":"<p>L'élément clé est le <strong>rythme de la douleur</strong>.</p>"},{"i":"be4442119a9f","n":200,"o":"200-3","u":"Diagnostic positif","t":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","q":"Quelles sont les caractéristiques de l'horaire d'une douleur inflammatoire, et de la durée du dérouillage matinal ?","a":"<ul><li>Elle est <strong>aggravée en deuxième partie de nuit</strong>, avec des réveils nocturnes.</li><li>Le dérouillage matinal est <strong>supérieur à 45 minutes</strong>.</li></ul>"},{"i":"fcca2bfd262b","n":200,"o":"200-3","u":"Diagnostic positif","t":"Connaître la différence entre une douleur mécanique et une douleur inflammatoire","q":"Quelles sont les caractéristiques de l'horaire d'une douleur mécanique, et de la durée du dérouillage matinal ?","a":"<ul><li>Elle est <strong>maximale en fin de journée</strong>.</li><li>Il n'y a pas de réveil nocturne, sauf au changement de position.</li><li>Le dérouillage matinal est <strong>inférieur à 30 minutes</strong>.</li></ul>"},{"i":"4a514d0a1d18","n":200,"o":"200-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement articulaire","q":"Quelle est la conduite à tenir systématique devant un épanchement articulaire inexpliqué ?","a":"<p>Devant un épanchement articulaire inexpliqué, la <strong>ponction articulaire</strong> est systématique. C'est le seul examen permettant d'obtenir un <strong>diagnostic étiologique</strong> grâce à l'analyse du liquide (cytologie, microbiologie, recherche de cristaux).</p>"},{"i":"859c51525ef8","n":200,"o":"200-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement articulaire","q":"Comment est réalisé le diagnostic clinique d'un épanchement articulaire au niveau d'une articulation superficielle ?","a":"<p>Le diagnostic d'un épanchement articulaire superficiel est réalisé par :</p><ul><li><strong>Inspection</strong> : recherche d'une <strong>tuméfaction globale</strong> de l'articulation avec diminution des reliefs anatomiques.</li><li><strong>Palpation</strong> : confirmant l'épanchement, par exemple par le signe du <strong>choc patellaire</strong> ou du <strong>flot rotulien</strong> au genou.</li></ul>"},{"i":"cbdec5619dfd","n":200,"o":"200-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement articulaire","q":"Quelle est la particularité du diagnostic clinique d'un épanchement articulaire au niveau d'une articulation profonde (hanche, épaule) ?","a":"<p>Pour les articulations profondes comme la <strong>hanche</strong> ou l'<strong>épaule</strong>, la recherche directe d'un épanchement à l'examen clinique est impossible. Seule la <strong>limitation douloureuse des amplitudes articulaires</strong> peut être analysée.</p>"},{"i":"f45defe42832","n":200,"o":"200-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement articulaire","q":"Quand l'imagerie est-elle utile pour le diagnostic d'un épanchement articulaire, et quel type d'imagerie est principalement utilisé ?","a":"<p>L'imagerie est utilisée en complément du diagnostic clinique :</p><ul><li>En cas de <strong>doute clinique</strong>.</li><li>Pour la recherche d'épanchement dans une <strong>articulation profonde</strong> (ex: hanche).</li></ul><p>L'<strong>échographie</strong> est l'examen de choix, et elle peut également guider une ponction articulaire.</p>"},{"i":"3e211bb5fe39","n":200,"o":"200-5","u":"Diagnostic positif","t":"Connaître trois diagnostics différentiels d’un épanchement articulaire","q":"Quelles sont les caractéristiques cliniques permettant de différencier une ténosynovite d'un épanchement articulaire ?","a":"<p>La ténosynovite se manifeste par un épanchement situé spécifiquement dans les <strong>gaines synoviales tendineuses</strong>, autour du tendon, et non à l'intérieur de la cavité articulaire elle-même. Les zones fréquemment touchées sont la cheville et les tendons extenseurs des doigts.</p>"},{"i":"54a25908c864","n":200,"o":"200-5","u":"Diagnostic positif","t":"Connaître trois diagnostics différentiels d’un épanchement articulaire","q":"Quels sont les signes distinctifs d'une bursite ou d'un hygroma par rapport à un épanchement articulaire ?","a":"<p>La bursite ou l'hygroma correspondent à l'inflammation d'une <strong>bourse séreuse de glissement</strong>. Cliniquement, les <strong>amplitudes articulaires ne sont pas limitées</strong> et la mobilisation passive est conservée, contrairement à un épanchement articulaire.</p>"},{"i":"7e1a593527a0","n":200,"o":"200-5","u":"Diagnostic positif","t":"Connaître trois diagnostics différentiels d’un épanchement articulaire","q":"Comment distinguer un épanchement articulaire véritable d'une tuméfaction péri-articulaire à l'examen clinique ?","a":"<p>La caractéristique discriminante majeure est que, dans le cas d'une tuméfaction péri-articulaire mimant un épanchement, les <strong>amplitudes articulaires sont conservées</strong> tandis qu'elles sont altérées dans un épanchement intra-articulaire.</p>"},{"i":"bd9c8580c3be","n":200,"o":"200-5","u":"Diagnostic positif","t":"Connaître trois diagnostics différentiels d’un épanchement articulaire","q":"Comment différencier un érysipèle ou une thrombose veineuse profonde (TVP) d'un épanchement articulaire ?","a":"<ul><li>Un <strong>érysipèle</strong> est un érythème superficiel et mobile, représentant une dermohypodermite, sans limitation articulaire.</li><li>Une <strong>thrombose veineuse profonde (TVP)</strong> se manifeste par un œdème douloureux des parties molles, sans atteinte directe de la cavité articulaire.</li></ul>"},{"i":"9fd4d5c79f5a","n":200,"o":"200-6","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’une arthrite septique","q":"Quel est le geste diagnostique central en cas de suspicion d'arthrite septique, et quand doit-il être réalisé ?","a":"<p>Le geste diagnostique central est la <strong>ponction articulaire</strong>. Elle doit être réalisée <strong>en urgence</strong> et impérativement <strong>avant toute antibiothérapie ou corticothérapie</strong>, afin d'éviter les faux-négatifs des cultures bactériologiques.</p>"},{"i":"e72a3e76d8cf","n":200,"o":"200-6","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’une arthrite septique","q":"Quels sont les éléments clés de l'analyse du liquide synovial dans le diagnostic d'une arthrite septique ?","a":"<ul><li><strong>Aspect macroscopique évocateur</strong> : liquide puriforme (aspect laiteux), trouble, parfois purulent et hémorragique dans les formes sévères.</li><li><strong>Analyse cytologique</strong> : liquide inflammatoire avec <strong>plus de 2 000 leucocytes/mL</strong>, à prédominance de polynucléaires neutrophiles (PNN). La formule n'est cependant pas spécifique de l'étiologie.</li><li><strong>Analyse microbiologique indispensable</strong> : <strong>examen direct et culture</strong>, à prolonger 14 jours si forte suspicion. La mise en mycobactériologie est réservée à la suspicion de tuberculose articulaire.</li></ul>"},{"i":"ec1fb7b5f0bb","n":200,"o":"200-6","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’une arthrite septique","q":"Quels sont les signes radiographiques observés en cas d'arthrite septique non traitée, et à quel stade apparaissent-ils ?","a":"<p>Les signes radiographiques sont des <strong>signes tardifs</strong>, apparaissant au stade de séquelle en l'absence de traitement :</p><ul><li><strong>Déminéralisation épiphysaire en bandes</strong> : visible entre J10 et J14.</li><li><strong>Pincement diffus de l'interligne articulaire</strong> et <strong>érosions osseuses sous-chondrales</strong> : visibles entre J21 et J28.</li><li>Un <strong>signe négatif utile</strong> est <strong>l'absence d'ostéophyte</strong>, contrairement à l'arthrose.</li></ul>"},{"i":"f1a1d326c74d","n":200,"o":"200-6","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’une arthrite septique","q":"Quelle est l'attitude initiale à adopter devant toute monoarthrite, et pourquoi ?","a":"<p>Toute monoarthrite est une <strong>arthrite septique jusqu'à preuve du contraire</strong>. Il s'agit d'une <strong>urgence diagnostique et thérapeutique</strong> en raison du risque de destruction articulaire rapide et de sepsis.</p>"},{"i":"ffa59ddd63fe","n":200,"o":"200-6","u":"Identifier une urgence","t":"Connaître les modalités du diagnostic d’une arthrite septique","q":"Quels sont les examens complémentaires à visée étiologique à réaliser pour une arthrite septique, en dehors de l'analyse du liquide synovial ?","a":"<ul><li><strong>Hémocultures</strong> : à la recherche d'une porte d'entrée ou d'une bactériémie.</li><li><strong>Recherche de porte d'entrée</strong> : orientée par le contexte clinique (ex: chirurgie articulaire récente, infiltration cortisonique).</li><li><strong>Biopsie synoviale</strong> : peut-être nécessaire dans certains cas pour affirmer le diagnostic.</li></ul>"},{"i":"083c539c6d8d","n":200,"o":"200-8","u":"Étiologies","t":"Connaître les principales étiologies à évoquer devant une arthrite récente","q":"Comment différencier une polyarthrite rhumatoïde d'une spondyloarthrite périphérique par la topographie de l'atteinte articulaire ?","a":"<p>La différenciation se fait par la topographie de l'atteinte articulaire :</p><ul><li>La <strong>polyarthrite rhumatoïde</strong> se caractérise par une atteinte <strong>distale et symétrique</strong>.</li><li>La <strong>spondyloarthrite périphérique</strong> se manifeste par une atteinte <strong>oligo-articulaire asymétrique des membres inférieurs</strong>.</li></ul>"},{"i":"36f2ebd5fc9a","n":200,"o":"200-8","u":"Étiologies","t":"Connaître les principales étiologies à évoquer devant une arthrite récente","q":"Quelle est la première étiologie à éliminer en urgence devant une arthrite récente ?","a":"<p>La première étiologie à éliminer en urgence devant une arthrite récente est l'<strong>arthrite septique</strong>.</p>"},{"i":"57cb3c6cdcc4","n":200,"o":"200-8","u":"Étiologies","t":"Connaître les principales étiologies à évoquer devant une arthrite récente","q":"Quelle est l'étiologie la plus fréquente des arthrites microcristallines et ses caractéristiques principales ?","a":"<p>L'étiologie la plus fréquente des arthrites microcristallines est la <strong>goutte</strong>, caractérisée par des cristaux d'<strong>urate de sodium</strong>. Elle se manifeste typiquement par une <strong>monoarthrite de la première articulation métatarso-phalangienne (MTP1)</strong>.</p>"},{"i":"650cb31df859","n":200,"o":"200-8","u":"Étiologies","t":"Connaître les principales étiologies à évoquer devant une arthrite récente","q":"Quels éléments orientent vers une arthrite septique devant une arthrite récente ?","a":"<p>Devant une arthrite récente, une arthrite septique est évoquée en présence de :</p><ul><li>Un <strong>contexte infectieux</strong>.</li><li>Une <strong>porte d'entrée</strong> (ex: chirurgie articulaire, infiltration).</li><li>De la <strong>fièvre</strong>.</li><li>Un <strong>liquide articulaire puriforme</strong>.</li></ul>"},{"i":"146c16c7ffef","n":200,"o":"200-9","u":"Étiologies","t":"Connaître les cinq causes principales d’un épanchement articulaire mécanique","q":"Comment se caractérise un épanchement articulaire mécanique à l'analyse du liquide synovial ?","a":"<p>Un épanchement mécanique donne un liquide synovial <strong>jaune citrin</strong>, <strong>translucide</strong>, <strong>visqueux</strong>, <strong>pauvre en cellules</strong> (<strong>&lt; 2 000 leucocytes/mL</strong>), <strong>stérile</strong> et <strong>sans cristaux</strong>.</p>"},{"i":"b39f5f8cc9cd","n":200,"o":"200-9","u":"Étiologies","t":"Connaître les cinq causes principales d’un épanchement articulaire mécanique","q":"Quelle est la cause la plus fréquente d'un épanchement articulaire mécanique ?","a":"<p>La cause la plus fréquente d'un épanchement articulaire mécanique est l'<strong>arthrose en poussée</strong>.</p>"},{"i":"c8d39716731c","n":200,"o":"200-9","u":"Étiologies","t":"Connaître les cinq causes principales d’un épanchement articulaire mécanique","q":"Quelles sont les cinq causes principales d'un épanchement articulaire mécanique ?","a":"<ul><li><strong>Arthrose en poussée</strong> (cause la plus fréquente)</li><li><strong>Lésion méniscale</strong></li><li><strong>Lésion chondrale / ostéochondrite</strong></li><li><strong>Ostéonécrose aseptique</strong></li><li><strong>Algodystrophie</strong></li></ul>"}]};